node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { Ledger } from './src/ledger.mjs';

const ledger = new Ledger({ a: 100, b: 0 });
const repeated = { id: 'same', from: 'a', to: 'b', amount: 20 };
assert.deepEqual(ledger.applyBatch([repeated, { ...repeated }]), { a: 80, b: 20 });
const before = ledger.snapshot();
assert.throws(() => ledger.applyBatch([
  { id: 'later', from: 'a', to: 'b', amount: 10 },
  { id: 'bad', from: 'a', to: 'missing', amount: 1 }
]));
assert.deepEqual(ledger.snapshot(), before);
assert.deepEqual(ledger.applyBatch([{ ...repeated }]), before);
assert.throws(() => ledger.applyBatch([{ ...repeated, amount: 21 }]), /Conflicting/);
assert.deepEqual(ledger.snapshot(), before);
assert.throws(() => ledger.applyBatch([{ id: 'invalid', from: 1, to: 'b', amount: 1 }]));
const special = Object.create(null);
special.__proto__ = 50;
special.target = 0;
assert.deepEqual(new Ledger(special).applyBatch([{ id: 'special', from: '__proto__', to: 'target', amount: 10 }]), { __proto__: 40, target: 10 });
console.log('custom ledger contract checks passed');
EOF

