export function applyTransfer(balances, transfer) {
  const { from, to, amount } = transfer;
  if (typeof from !== 'string' || typeof to !== 'string') throw new Error('Invalid account id');
  if (!Object.hasOwn(balances, from) || !Object.hasOwn(balances, to)) throw new Error('Unknown account');
  if (!Number.isSafeInteger(amount) || amount <= 0) throw new Error('Invalid amount');

  const sourceBalance = balances[from];
  const destinationBalance = balances[to];
  if (!Number.isSafeInteger(sourceBalance) || sourceBalance < 0
    || !Number.isSafeInteger(destinationBalance) || destinationBalance < 0) {
    throw new Error('Invalid balance');
  }
  if (sourceBalance < amount) throw new Error('Insufficient funds');
  if (from === to) return;

  const nextSourceBalance = sourceBalance - amount;
  const nextDestinationBalance = destinationBalance + amount;
  if (!Number.isSafeInteger(nextDestinationBalance)) throw new Error('Invalid balance');

  Object.defineProperty(balances, from, {
    value: nextSourceBalance, enumerable: true, configurable: true, writable: true
  });
  Object.defineProperty(balances, to, {
    value: nextDestinationBalance, enumerable: true, configurable: true, writable: true
  });
}
export function sameTransfer(a, b) { return a.from === b.from && a.to === b.to && a.amount === b.amount; }
